def sha256_file(path: str) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def strip_oni_markup(text: str) -> str:
    if not text:
        return ""
    text = re.sub(r"<[^>]+>", "", text)
    text = text.replace("\\n", " ").replace("\n", " ")
    text = re.sub(r"\s+", " ", text).strip()
    return text


def parse_ko_po(po_path: str) -> dict:
    """Fast lightweight PO parser mapping msgctxt -> msgstr."""
    ko = {}
    ctx = None
    msgstr_lines = []
    in_msgstr = False

    def flush():
        nonlocal ctx, msgstr_lines, in_msgstr
        if ctx and msgstr_lines:
            val = "".join(msgstr_lines)
            if val:
                ko[ctx] = strip_oni_markup(val)
        ctx = None
        msgstr_lines = []
        in_msgstr = False

    with open(po_path, "r", encoding="utf-8", errors="replace") as f:
        for raw_line in f:
            line = raw_line.strip()
            if not line:
                flush()
                continue
            if line.startswith("#"):
                continue
            if line.startswith("msgctxt "):
                flush()
                m = re.match(r'msgctxt\s+"(.*)"', line)
                if m:
                    ctx = m.group(1)
            elif line.startswith("msgstr "):
                in_msgstr = True
                m = re.match(r'msgstr\s+"(.*)"', line)
                if m:
                    msgstr_lines.append(m.group(1))
            elif line.startswith('"') and in_msgstr:
                m = re.match(r'"(.*)"', line)
                if m:
                    msgstr_lines.append(m.group(1))
    flush()
    return ko


def fallback_color(el_id: str, state: str) -> list:
    if el_id in ELEMENT_COLORS:
        return ELEMENT_COLORS[el_id]
    h = int(hashlib.md5(el_id.encode("utf-8")).hexdigest()[:6], 16)
    r = ((h >> 16) & 255) / 255.0
    g = ((h >> 8) & 255) / 255.0
    b = (h & 255) / 255.0
    if state == "gas":
        return [round(0.35 + r * 0.55, 3), round(0.45 + g * 0.45, 3), round(0.50 + b * 0.45, 3)]
    if state == "liquid":
        return [round(0.15 + r * 0.45, 3), round(0.35 + g * 0.45, 3), round(0.50 + b * 0.45, 3)]
    return [round(0.25 + r * 0.50, 3), round(0.22 + g * 0.45, 3), round(0.20 + b * 0.45, 3)]


def extract_elements(streaming_dir: str, ko: dict) -> dict:
    out = {}
    files = ["gas.yaml", "liquid.yaml", "solid.yaml", "special.yaml"]
    for fname in files:
        fpath = os.path.join(streaming_dir, "elements", fname)
        if not os.path.exists(fpath):
            continue
        with open(fpath, "r", encoding="utf-8") as f:
            doc = yaml.safe_load(f) or {}
        for item in doc.get("elements", []):
            eid = item.get("elementId")
            if not eid or item.get("isDisabled", False):
                continue
            state_raw = str(item.get("state", "Solid")).lower()
            if state_raw not in ("gas", "liquid", "solid"):
                state_raw = "gas" if eid == "Vacuum" else "solid"
            loc_id = str(item.get("localizationID", f"STRINGS.ELEMENTS.{eid.upper()}.NAME"))
            name_ko = ko.get(loc_id, eid)

            def k_to_c(v):
                if v is None:
                    return None
                return round(float(v) - 273.15, 2)

            hardness = float(item.get("hardness", 25))
            undiggable = (hardness >= 250) or (eid in ("Unobtanium", "Katairite"))
            dig_time = 999.0 if undiggable else round(max(1.0, min(6.0, hardness / 12.0)), 2)

            out[eid] = {
                "name_ko": name_ko,
                "state": state_raw,
                "shc": round(float(item.get("specificHeatCapacity", 1.0)), 5),
                "tc": round(float(item.get("thermalConductivity", 1.0)), 5),
                "molar_mass": round(float(item.get("molarMass", 20.0)), 5),
                "default_mass": round(float(item.get("defaultMass", item.get("defaultPressure", 1.0))), 3),
                "max_mass": round(float(item.get("maxMass", 1000.0)), 3),
                "default_temp_c": k_to_c(item.get("defaultTemperature", 295.15)),
                "low_c": k_to_c(item.get("lowTemp")),
                "low_target": item.get("lowTempTransitionTarget"),
                "high_c": k_to_c(item.get("highTemp")),
                "high_target": item.get("highTempTransitionTarget"),
                "sublimate_id": item.get("sublimateId"),
                "light_abs": round(float(item.get("lightAbsorptionFactor", 0.0)), 3),
                "hardness": hardness,
                "dig_time": dig_time,
                "undiggable": undiggable,
                "color": fallback_color(eid, state_raw),
            }
    return out


def extract_worldgen(streaming_dir: str) -> dict:
    wg_dir = os.path.join(streaming_dir, "worldgen")

    # 1) Temperatures
    temps = {}
    tpath = os.path.join(wg_dir, "temperatures.yaml")
    if os.path.exists(tpath):
        with open(tpath, "r", encoding="utf-8") as f:
            tdoc = yaml.safe_load(f) or {}
        for k, v in (tdoc.get("ranges") or {}).items():
            temps[k] = {
                "min_c": round(float(v.get("min", 293.15)) - 273.15, 2),
                "max_c": round(float(v.get("max", 295.15)) - 273.15, 2),
            }

    # 2) Biomes
    biomes = {}
    bdir = os.path.join(wg_dir, "biomes")
    if os.path.isdir(bdir):
        for fname in sorted(os.listdir(bdir)):
            if not fname.endswith(".yaml"):
                continue
            bname = os.path.splitext(fname)[0]
            with open(os.path.join(bdir, fname), "r", encoding="utf-8") as f:
                bdoc = yaml.safe_load(f) or {}
            table = bdoc.get("TerrainBiomeLookupTable") or {}
            bands = []
            for table_key, entries in table.items():
                if not isinstance(entries, list):
                    continue
                for ent in entries:
                    if isinstance(ent, dict) and "content" in ent:
                        bands.append({
                            "table": table_key,
                            "element": ent["content"],
                            "band_size": round(float(ent.get("bandSize", 0.2)), 4),
                        })
            biomes[bname] = {
                "band_count": len(bands),
                "bands": bands[:24],
            }

    # 3) Starting base template (sandstoneBase.yaml)
    base_tpl = {"size": {"x": 18, "y": 7}, "cells": [], "buildings": []}
    sb_path = os.path.join(streaming_dir, "templates", "bases", "sandstoneBase.yaml")
    if os.path.exists(sb_path):
        with open(sb_path, "r", encoding="utf-8") as f:
            sb = yaml.safe_load(f) or {}
        info = sb.get("info") or {}
        sz = info.get("size") or {}
        mn = info.get("min") or {}
        base_tpl["size"] = {"x": int(sz.get("X", 18)), "y": int(sz.get("Y", 7))}
        base_tpl["min"] = {"x": int(mn.get("X", -8)), "y": int(mn.get("Y", -2))}
        for c in sb.get("cells") or []:
            base_tpl["cells"].append({
                "x": int(c.get("location_x", 0)),
                "y": int(c.get("location_y", 0)),
                "element": str(c.get("element", "Oxygen")),
                "mass": round(float(c.get("mass", 1.0)), 3),
                "temp_c": round(float(c.get("temperature", 295.15)) - 273.15, 2),
            })
        for b in sb.get("buildings") or []:
            base_tpl["buildings"].append({
                "id": str(b.get("id", "")),
                "x": int(b.get("location_x", 0)),
                "y": int(b.get("location_y", 0)),
                "element": str(b.get("element", "SandStone")),
            })

    return {
        "temperatures": temps,
        "biomes": biomes,
        "sandstone_base": base_tpl,
    }


def extract_tech_tree(data_dir: str, ko: dict) -> dict:
    res_path = os.path.join(data_dir, "resources.assets")
    with open(res_path, "rb") as f:
        raw = f.read()

    graphs = []
    for m in re.finditer(rb"<graphml.*?</graphml>", raw, re.DOTALL):
        xml_str = m.group(0).decode("utf-8", errors="replace")
        # Strip xml:space or undeclared prefixes if any
        xml_str = re.sub(r'\s+yfiles\.[a-zA-Z0-9_]+="[^"]*"', "", xml_str)
        try:
            root = ET.fromstring(xml_str)
        except ET.ParseError:
            continue
        id_map = {}
        nodes = {}
        for node in root.iter():
            if not node.tag.endswith("node"):
                continue
            # Skip group container nodes (those that contain nested <graph> children)
            if any(ch.tag.endswith("graph") for ch in node):
                continue
            raw_id = node.attrib.get("id", "")
            if not raw_id:
                continue
            label_text = ""
            gx, gy = 0.0, 0.0
            for elem in node.iter():
                if elem.tag.endswith("NodeLabel") and elem.text and elem.text.strip():
                    label_text = elem.text.strip()
                elif elem.tag.endswith("Geometry"):
                    gx = round(float(elem.attrib.get("x", "0")), 1)
                    gy = round(float(elem.attrib.get("y", "0")), 1)
            if not label_text:
                continue
            id_map[raw_id] = label_text
            nodes[label_text] = {"id": label_text, "prereqs": [], "x": gx, "y": gy}
        edges = []
        for edge in root.iter():
            if not edge.tag.endswith("edge"):
                continue
            src = id_map.get(edge.attrib.get("source", ""), "")
            tgt = id_map.get(edge.attrib.get("target", ""), "")
            if src in nodes and tgt in nodes:
                nodes[tgt]["prereqs"].append(src)
                edges.append([src, tgt])
        if nodes:
            graphs.append((len(nodes), nodes, edges))

    # Pick base-game tech tree (86 techs; Graph 1 is base game, Graph 0 is Spaced Out DLC)
    graphs.sort(key=lambda g: abs(g[0] - 86))
    if not graphs:
        return {"techs": {}, "edge_count": 0}

    _, nodes, edges = graphs[0]

    # Compute tier by longest prerequisite depth
    memo = {}

    def get_tier(nid: str, seen=None) -> int:
        if nid in memo:
            return memo[nid]
        seen = seen or set()
        if nid in seen:
            return 1
        seen.add(nid)
        ps = nodes[nid]["prereqs"]
        t = 1 if not ps else 1 + max(get_tier(p, seen) for p in ps)
        memo[nid] = t
        return t

    techs = {}
    for nid, nd in sorted(nodes.items(), key=lambda kv: (get_tier(kv[0]), kv[1]["y"], kv[0])):
        tier = get_tier(nid)
        upper = nid.upper()
        name_ko = ko.get(f"STRINGS.RESEARCH.TECHS.{upper}.NAME", nid)
        desc_ko = ko.get(f"STRINGS.RESEARCH.TECHS.{upper}.DESC", "")
        # Standard ONI tier research point schedule
        basic_cost = min(50.0, 10.0 + (tier - 1) * 5.0)
        adv_cost = 0.0 if tier <= 2 else min(60.0, (tier - 2) * 15.0)
        techs[nid] = {
            "id": nid,
            "name_ko": name_ko,
            "desc": desc_ko,
            "tier": tier,
            "cost_basic": basic_cost,
            "cost_advanced": adv_cost,
            "prereqs": sorted(set(nd["prereqs"])),
            "unlocks": TECH_BUILDING_MAP.get(nid, []),
            "x": nd["x"],
            "y": nd["y"],
        }

    return {
        "tech_count": len(techs),
        "edge_count": len(edges),
        "techs": techs,
    }


def extract_buildings(ko: dict) -> dict:
    out = {}
    for bid, meta in BUILDING_PREFAB_MAP.items():
        pf = meta["prefab"]
        entry = dict(meta)
        entry["name_ko"] = ko.get(f"STRINGS.BUILDINGS.PREFABS.{pf}.NAME", bid)
        entry["desc"] = ko.get(f"STRINGS.BUILDINGS.PREFABS.{pf}.EFFECT", ko.get(f"STRINGS.BUILDINGS.PREFABS.{pf}.DESC", ""))
        out[bid] = entry
    return out


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--source", default=r"C:\Temp\Oxygen")
    parser.add_argument(
        "--out",
        default=r"D:\Github\GoDotProjects-worktrees\breath-sim\forge\Templates\oxygen-not-included\data",
    )
    args = parser.parse_args()

    data_dir = os.path.join(args.source, "OxygenNotIncluded_Data")
    streaming_dir = os.path.join(data_dir, "StreamingAssets")
    po_path = os.path.join(streaming_dir, "strings", "strings_preinstalled_ko_klei.po")

    if not os.path.isdir(streaming_dir):
        print(f"ERROR: StreamingAssets not found at {streaming_dir}", file=sys.stderr)
        return 1

    os.makedirs(args.out, exist_ok=True)
    ko = parse_ko_po(po_path) if os.path.exists(po_path) else {}

    elements = extract_elements(streaming_dir, ko)
    worldgen = extract_worldgen(streaming_dir)
    tech_tree = extract_tech_tree(data_dir, ko)
    buildings = extract_buildings(ko)

    def write_json(name: str, obj: dict) -> str:
        p = os.path.join(args.out, name)
        with open(p, "w", encoding="utf-8") as f:
            json.dump(obj, f, ensure_ascii=False, separators=(",", ":"))
        return p

    write_json("elements_extracted.txt", elements)
    write_json("biomes_worldgen_extracted.txt", worldgen)
    write_json("tech_tree_extracted.txt", tech_tree)
    write_json("buildings_extracted.txt", buildings)

    manifest = {
        "source_path": args.source,
        "extracted_at_utc": datetime.now(timezone.utc).isoformat(),
        "counts": {
            "ko_strings": len(ko),
            "elements": len(elements),
            "biomes": len(worldgen["biomes"]),
            "sandstone_base_cells": len(worldgen["sandstone_base"]["cells"]),
            "sandstone_base_buildings": len(worldgen["sandstone_base"]["buildings"]),
            "techs": tech_tree["tech_count"],
            "tech_edges": tech_tree["edge_count"],
            "buildings": len(buildings),
        },
        "source_hashes_sha256": {
            "gas.yaml": sha256_file(os.path.join(streaming_dir, "elements", "gas.yaml")),
            "liquid.yaml": sha256_file(os.path.join(streaming_dir, "elements", "liquid.yaml")),
            "solid.yaml": sha256_file(os.path.join(streaming_dir, "elements", "solid.yaml")),
            "sandstoneBase.yaml": sha256_file(os.path.join(streaming_dir, "templates", "bases", "sandstoneBase.yaml")),
        },
    }
    with open(os.path.join(args.out, "extraction_manifest.txt"), "w", encoding="utf-8") as f:
        json.dump(manifest, f, ensure_ascii=False, indent=2)

    print(json.dumps(manifest["counts"], ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
